SELECT DISTINCT "officelocation" AS rental_property_location
FROM "teachers"
WHERE "officelocation" IS NOT NULL;

286:
SELECT DISTINCT d."degree_level"
FROM "degrees" d
WHERE LOWER(d."job_post") LIKE LOWER('%AI Researcher%');

